-- m004: custom wrapper intake (F-039).
-- m001's adapter_versions.source CHECK omitted 'custom', the provenance label
-- for wrapper modules submitted over MCP by an external GenAI session
-- (wrapper_load operator tool) rather than generated by the converter or
-- shipped built-in; the audit_events.kind CHECK likewise has no 'wrapper'
-- kind for intake/removal events. SQLite cannot alter a CHECK constraint in
-- place, so both tables are rebuilt (data preserved); foreign_keys is OFF
-- during the rebuild because tools.version_id references adapter_versions(id).

PRAGMA foreign_keys = OFF;

CREATE TABLE IF NOT EXISTS adapter_versions_new (
  id              INTEGER PRIMARY KEY,
  adapter_module  TEXT    NOT NULL,
  version_hash    TEXT    NOT NULL,
  source          TEXT    NOT NULL
                  CHECK (source IN ('built-in', 'generated', 'manual', 'custom')),
  parent_id       INTEGER REFERENCES adapter_versions_new(id),
  created_ts      REAL    NOT NULL
);
INSERT INTO adapter_versions_new SELECT * FROM adapter_versions;
DROP TABLE adapter_versions;
ALTER TABLE adapter_versions_new RENAME TO adapter_versions;
CREATE INDEX IF NOT EXISTS idx_versions_module
  ON adapter_versions(adapter_module, created_ts);

CREATE TABLE IF NOT EXISTS audit_events_new (
  id            INTEGER PRIMARY KEY,
  ts            REAL    NOT NULL,
  kind          TEXT    NOT NULL
                CHECK (kind IN ('verdict', 'merge', 'repair', 'quarantine',
                                'config', 'install', 'rejection', 'wrapper')),
  actor         TEXT    NOT NULL,
  payload_json  TEXT    NOT NULL
);
INSERT INTO audit_events_new SELECT * FROM audit_events;
DROP TABLE audit_events;
ALTER TABLE audit_events_new RENAME TO audit_events;
CREATE INDEX IF NOT EXISTS idx_audit_kind_ts ON audit_events(kind, ts);

PRAGMA foreign_keys = ON;
